'use client';

import { useEffect, useMemo, useRef, useState } from 'react';
import { CheckCircle2, ClipboardCheck, RotateCcw, ShieldCheck, UserRound, Wrench } from 'lucide-react';
import { createStoreClient } from '@/lib/supabase/storeClient';
import { ZEUS_CHECKLIST_TEMPLATES, type ZeusChecklistSegment } from '@/lib/operations/checklistTemplates';

type LinkData={appId:string;kind:string;recordId?:string;title:string;payload:Record<string,any>;status:string};
type Answer={status:string;note:string};
type DamageType='Amassado'|'Riscado'|'Quebrado'|'Faltante';
type Damage={view:string;point:string;type:DamageType};

async function invoke(token:string,action:'read'|'respond',response?:Record<string,unknown>){
  const {data,error}=await createStoreClient().functions.invoke('external-link',{body:{token,action,response}});
  if(error)throw error;if(data?.error)throw new Error(data.error);return data;
}

function SignaturePad({label,value,onChange}:{label:string;value:string;onChange:(value:string)=>void}){
  const ref=useRef<HTMLCanvasElement>(null);const drawing=useRef(false);
  useEffect(()=>{const canvas=ref.current;if(!canvas)return;const ratio=Math.max(1,window.devicePixelRatio||1);const box=canvas.getBoundingClientRect();canvas.width=Math.floor(box.width*ratio);canvas.height=Math.floor(112*ratio);const ctx=canvas.getContext('2d');if(!ctx)return;ctx.scale(ratio,ratio);ctx.lineWidth=2;ctx.lineCap='round';ctx.strokeStyle='#102a4f';},[]);
  const point=(event:React.PointerEvent<HTMLCanvasElement>)=>{const rect=event.currentTarget.getBoundingClientRect();return{x:event.clientX-rect.left,y:event.clientY-rect.top};};
  const start=(event:React.PointerEvent<HTMLCanvasElement>)=>{drawing.current=true;event.currentTarget.setPointerCapture(event.pointerId);const ctx=event.currentTarget.getContext('2d');const p=point(event);ctx?.beginPath();ctx?.moveTo(p.x,p.y);};
  const move=(event:React.PointerEvent<HTMLCanvasElement>)=>{if(!drawing.current)return;const ctx=event.currentTarget.getContext('2d');const p=point(event);ctx?.lineTo(p.x,p.y);ctx?.stroke();};
  const end=()=>{drawing.current=false;const canvas=ref.current;if(canvas)onChange(canvas.toDataURL('image/png',0.7));};
  const clear=()=>{const canvas=ref.current;const ctx=canvas?.getContext('2d');if(canvas&&ctx){ctx.clearRect(0,0,canvas.width,canvas.height);onChange('');}};
  return <div className="signature-box"><div className="signature-head"><strong>{label}</strong><button type="button" onClick={clear}><RotateCcw size={13}/>Limpar</button></div><canvas ref={ref} onPointerDown={start} onPointerMove={move} onPointerUp={end} onPointerCancel={end}/><small>{value?'Assinatura registrada.':'Assine dentro da área acima.'}</small></div>;
}

const colors:Record<DamageType,string>={Amassado:'#dc2626',Riscado:'#2563eb',Quebrado:'#f97316',Faltante:'#7c3aed'};
const views:Record<ZeusChecklistSegment,string[]>={auto:['Superior','Frontal','Traseira','Lateral esquerda','Lateral direita'],moto:['Frontal','Traseira','Lateral esquerda','Lateral direita'],truck:['Frontal','Traseira','Lateral esquerda','Lateral direita'],machine:['Frontal','Traseira','Lateral esquerda','Lateral direita']};

function VehicleDrawing({segment,view}:{segment:ZeusChecklistSegment;view:string}){
  const stroke='#375274';const fill='#eef3f8';const glass='#d8e7f5';
  if(segment==='moto')return <svg viewBox="0 0 320 150" aria-label={`Moto ${view}`}><circle cx="72" cy="112" r="28" fill="none" stroke={stroke} strokeWidth="7"/><circle cx="246" cy="112" r="28" fill="none" stroke={stroke} strokeWidth="7"/><path d="M72 112L128 66L174 112L112 112L150 112L208 62L246 112" fill="none" stroke={stroke} strokeWidth="7" strokeLinecap="round" strokeLinejoin="round"/><path d="M127 67h62l24 24-73 4z" fill={fill} stroke={stroke} strokeWidth="4"/></svg>;
  if(segment==='truck'){
    if(view==='Frontal'||view==='Traseira')return <svg viewBox="0 0 320 150" aria-label={`Caminhão ${view}`}><rect x="105" y="18" width="110" height="106" rx="12" fill={fill} stroke={stroke} strokeWidth="4"/><rect x="122" y="35" width="76" height="38" rx="6" fill={glass} stroke={stroke} strokeWidth="3"/><rect x="126" y="87" width="68" height="20" rx="5" fill="#fff" stroke={stroke} strokeWidth="3"/><circle cx="122" cy="127" r="14" fill={stroke}/><circle cx="198" cy="127" r="14" fill={stroke}/></svg>;
    return <svg viewBox="0 0 320 150" aria-label={`Caminhão ${view}`}><rect x="119" y="39" width="157" height="70" rx="5" fill={fill} stroke={stroke} strokeWidth="4"/><path d="M46 109V69l36-28h37v68z" fill={fill} stroke={stroke} strokeWidth="4"/><rect x="63" y="59" width="35" height="25" rx="4" fill={glass} stroke={stroke} strokeWidth="3"/><circle cx="82" cy="116" r="17" fill={stroke}/><circle cx="205" cy="116" r="17" fill={stroke}/><circle cx="252" cy="116" r="17" fill={stroke}/></svg>;
  }
  if(segment==='machine')return <svg viewBox="0 0 320 150" aria-label={`Máquina ${view}`}><rect x="125" y="105" width="145" height="24" rx="12" fill={fill} stroke={stroke} strokeWidth="4"/><rect x="168" y="52" width="62" height="53" rx="8" fill={glass} stroke={stroke} strokeWidth="4"/><path d="M170 61L126 34L63 55" fill="none" stroke={stroke} strokeWidth="11" strokeLinecap="round"/><path d="M64 55L36 95" fill="none" stroke={stroke} strokeWidth="9" strokeLinecap="round"/><path d="M24 93l42-2-12 27-39-6z" fill={fill} stroke={stroke} strokeWidth="4"/><rect x="230" y="67" width="50" height="38" rx="7" fill={fill} stroke={stroke} strokeWidth="4"/></svg>;
  if(view==='Superior')return <svg viewBox="0 0 320 150" aria-label="Automóvel vista superior"><path d="M132 8q28-8 56 0l15 27v77l-15 29q-28 8-56 0l-15-29V35z" fill={fill} stroke={stroke} strokeWidth="4"/><rect x="131" y="36" width="58" height="35" rx="8" fill={glass} stroke={stroke} strokeWidth="3"/><rect x="131" y="79" width="58" height="33" rx="8" fill={glass} stroke={stroke} strokeWidth="3"/></svg>;
  if(view==='Frontal'||view==='Traseira')return <svg viewBox="0 0 320 150" aria-label={`Automóvel ${view}`}><path d="M105 126l8-67q8-42 47-42t47 42l8 67z" fill={fill} stroke={stroke} strokeWidth="4"/><path d="M126 60q8-27 34-27t34 27z" fill={glass} stroke={stroke} strokeWidth="3"/><rect x="127" y="86" width="66" height="20" rx="7" fill="#fff" stroke={stroke} strokeWidth="3"/></svg>;
  return <svg viewBox="0 0 320 150" aria-label={`Automóvel ${view}`}><circle cx="92" cy="117" r="20" fill={stroke}/><circle cx="235" cy="117" r="20" fill={stroke}/><path d="M35 112l15-38 48-12 30-36h70l34 34 50 15 11 37z" fill={fill} stroke={stroke} strokeWidth="4"/><path d="M135 35h56l28 26h-106z" fill={glass} stroke={stroke} strokeWidth="3"/></svg>;
}

function DamageBoard({segment,value,onChange}:{segment:ZeusChecklistSegment;value:Damage[];onChange:(next:Damage[])=>void}){
  const [type,setType]=useState<DamageType>('Amassado');
  const add=(view:string,event:React.MouseEvent<HTMLDivElement>)=>{const rect=event.currentTarget.getBoundingClientRect();const x=Math.round(((event.clientX-rect.left)/rect.width)*100);const y=Math.round(((event.clientY-rect.top)/rect.height)*100);onChange([...value,{view,point:`${x},${y}`,type}]);};
  return <section className="form-card damages"><div className="section-title"><Wrench size={18}/><div><h2>Avarias identificadas</h2><p>Escolha o tipo e clique diretamente na vista correspondente.</p></div></div><div className="damage-legend">{(Object.keys(colors) as DamageType[]).map(item=><button type="button" key={item} className={item===type?'selected':''} onClick={()=>setType(item)}><i style={{background:colors[item]}}/>{item}</button>)}</div><div className={`views-grid seg-${segment}`}>{views[segment].map(view=><div className="vehicle-view" key={view} onClick={event=>add(view,event)}><VehicleDrawing segment={segment} view={view}/><strong>{view}</strong>{value.filter(item=>item.view===view).map((item,index)=>{const [x,y]=item.point.split(',');return <button type="button" className="damage-dot" aria-label={`Remover ${item.type}`} onClick={event=>{event.stopPropagation();onChange(value.filter(current=>current!==item));}} key={`${item.point}-${index}`} style={{left:`${x}%`,top:`${y}%`,background:colors[item.type]}}>{index+1}</button>;})}</div>)}</div></section>;
}

export function ZeusCheckInPublic({token}:{token:string}){
  const [link,setLink]=useState<LinkData|null>(null);const [error,setError]=useState('');const [sent,setSent]=useState(false);const [name,setName]=useState('');const [phone,setPhone]=useState('');const [document,setDocument]=useState('');const [role,setRole]=useState('');const [notes,setNotes]=useState('');const [meter,setMeter]=useState('');const [customerSignature,setCustomerSignature]=useState('');const [staffSignature,setStaffSignature]=useState('');const [answers,setAnswers]=useState<Record<string,Answer>>({});const [damage,setDamage]=useState<Damage[]>([]);const [busy,setBusy]=useState(false);
  useEffect(()=>{void invoke(token,'read').then(result=>{if(result.link?.kind!=='zeus-checkin')throw new Error('Este link não é um checklist de entrada.');setLink(result.link);setMeter(String(result.link?.payload?.assetInfo?.meter||''));}).catch(reason=>setError(reason instanceof Error?reason.message:'Link indisponível.'));},[token]);
  const segment=(link?.payload?.segment&&ZEUS_CHECKLIST_TEMPLATES[link.payload.segment as ZeusChecklistSegment]?link.payload.segment:'auto') as ZeusChecklistSegment;
  const template=ZEUS_CHECKLIST_TEMPLATES[segment];
  const items=useMemo(()=>((link?.payload?.items||template.items) as string[]),[link,template.items]);
  const assetInfo=link?.payload?.assetInfo||{};
  if(error&&!link)return <main className="check-page"><section className="check-state"><h1>Este checklist não está disponível</h1><p>{error}</p></section></main>;
  if(!link)return <main className="check-page"><section className="check-state"><p>Abrindo checklist…</p></section></main>;
  if(sent)return <main className="check-page"><section className="check-state success"><CheckCircle2 size={46}/><h1>Checklist enviado</h1><p>O registro foi enviado para a oficina e ficará vinculado à OS.</p></section></main>;
  const submit=async()=>{if(!name.trim()){setError('Informe o responsável pela conferência.');return;}const missing=items.find(item=>!answers[item]?.status);if(missing){setError(`Responda o item: ${missing}`);return;}if(link.payload.requireSignature&&!customerSignature){setError('A assinatura do cliente/responsável é obrigatória.');return;}setBusy(true);setError('');try{await invoke(token,'respond',{segment,name:name.trim(),meter:meter.trim(),notes:notes.trim(),signature:customerSignature,customerSignature,staffSignature,contact:{phone,document,role},damage,answers:items.map(item=>({item,status:answers[item].status,note:answers[item].note||''}))});setSent(true);}catch(reason){setError(reason instanceof Error?reason.message:'Não foi possível enviar o checklist.');}finally{setBusy(false);}};
  const assetLabel=link.payload.assetLabel||template.shortLabel;const meterLabel=link.payload.meterLabel||(/máquina|equipamento/i.test(assetLabel)?'Horímetro':'Quilometragem');
  return <main className="check-page"><div className="check-wrap">
    <header className="check-top"><div><span className="brand">ZEUS <b>OFICINA</b></span><span className="divider"/> <span>CRM PLUS</span></div><div className="secure"><ShieldCheck size={17}/> Checklist externo seguro</div></header>
    <section className="check-heading"><div><p className="eyebrow">Checklist de entrada</p><h1>{template.shortLabel} · OS {String(link.payload.jobNumber||'').padStart(4,'0')}</h1><p>Inspeção visual e registro das condições no recebimento.</p></div><span className="status-pill">Em preenchimento</span></section>
    <section className="hero-data"><div><UserRound size={18}/><span>Cliente<strong>{link.payload.customer||'Não informado'}</strong></span></div><div><ClipboardCheck size={18}/><span>{link.payload.identifierLabel||'Identificação'}<strong>{assetInfo.identifier||link.payload.asset||'Não informado'}</strong></span></div><div><Wrench size={18}/><span>{assetLabel}<strong>{assetInfo.model||template.label}</strong></span></div></section>

    <div className="top-grid">
      <section className="form-card"><div className="section-title"><ClipboardCheck size={18}/><div><h2>Dados do {assetLabel.toLowerCase()}</h2><p>Informações principais do item recebido.</p></div></div><div className="fields"><label><span>Marca</span><input readOnly value={assetInfo.brand||''} placeholder="Não informado"/></label><label><span>Modelo</span><input readOnly value={assetInfo.model||''} placeholder="Não informado"/></label><label><span>{link.payload.identifierLabel||'Identificação'}</span><input readOnly value={assetInfo.identifier||''} placeholder="Não informado"/></label><label><span>Ano</span><input readOnly value={assetInfo.year||''} placeholder="Não informado"/></label><label><span>{meterLabel}</span><input value={meter} onChange={e=>setMeter(e.target.value)} placeholder="Informar"/></label></div></section>
      <section className="form-card"><div className="section-title"><UserRound size={18}/><div><h2>Dados do cliente / responsável</h2><p>Quem acompanha ou entrega o item.</p></div></div><div className="fields"><label className="wide"><span>Nome completo</span><input value={name} onChange={e=>setName(e.target.value)} placeholder="Nome do responsável"/></label><label><span>Telefone</span><input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="Telefone"/></label><label><span>Documento</span><input value={document} onChange={e=>setDocument(e.target.value)} placeholder="CPF/CNH ou identificação"/></label><label><span>Função</span><input value={role} onChange={e=>setRole(e.target.value)} placeholder="Cliente, motorista, operador..."/></label></div></section>
    </div>

    <section className="form-card inspection"><div className="section-title"><ClipboardCheck size={18}/><div><h2>Itens inspecionados</h2><p>Registre o status de cada item.</p></div><div className="status-key"><span><i className="ok"/>OK</span><span><i className="attention"/>Atenção</span><span><i className="na"/>N/A</span></div></div><div className="inspection-grid">{items.map((item,index)=>{const current=answers[item]||{status:'',note:''};return <div className="inspection-row" key={item}><div className="item-name"><b>{String(index+1).padStart(2,'0')}</b><span>{item}</span></div><div className="row-status">{['OK','Atenção','Não se aplica'].map(status=><button type="button" key={status} className={`${current.status===status?'active ':''}${status==='OK'?'ok':status==='Atenção'?'attention':'na'}`} onClick={()=>setAnswers({...answers,[item]:{...current,status}})}>{status==='Não se aplica'?'N/A':status}</button>)}</div><input value={current.note} onChange={e=>setAnswers({...answers,[item]:{...current,note:e.target.value}})} placeholder="Observação opcional"/></div>;})}</div></section>

    <DamageBoard segment={segment} value={damage} onChange={setDamage}/>

    <div className="bottom-grid"><section className="form-card notes"><div className="section-title"><ClipboardCheck size={18}/><div><h2>Observações gerais</h2><p>Registre ressalvas, objetos, condições ou informações adicionais.</p></div></div><textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Descreva outras informações relevantes..."/></section><section className="form-card signatures"><SignaturePad label="Assinatura do cliente / responsável" value={customerSignature} onChange={setCustomerSignature}/><SignaturePad label="Assinatura do responsável da oficina" value={staffSignature} onChange={setStaffSignature}/></section></div>
    {error&&<div className="check-error">{error}</div>}
    <footer className="check-actions"><span>Ao finalizar, o checklist ficará registrado na OS.</span><button disabled={busy} onClick={()=>void submit()}>{busy?'Enviando…':'Finalizar checklist'} <CheckCircle2 size={18}/></button></footer>
  </div>
  <style jsx global>{`
    *{box-sizing:border-box}body{margin:0;background:#edf2f7;color:#10213a;font-family:Inter,Arial,sans-serif}.check-page{min-height:100dvh;padding:20px}.check-wrap{max-width:1240px;margin:auto;display:grid;gap:12px}.check-top{height:58px;background:#102a4f;color:#fff;border-radius:14px;padding:0 20px;display:flex;align-items:center;justify-content:space-between;font-size:13px}.check-top>div{display:flex;align-items:center;gap:10px}.brand{font-size:20px;font-weight:900}.brand b{font-size:9px;color:#52a8ff;margin-left:4px;letter-spacing:.15em}.divider{width:1px;height:26px;background:#ffffff45}.secure{opacity:.9}.check-heading{background:#fff;border:1px solid #dce5ef;border-radius:14px;padding:18px 20px;display:flex;justify-content:space-between;align-items:center;box-shadow:0 4px 16px #19314f0a}.eyebrow{margin:0 0 4px;text-transform:uppercase;font-size:11px;font-weight:800;letter-spacing:.12em;color:#2c6ecf}.check-heading h1{font-size:30px;margin:0 0 4px}.check-heading p{margin:0;color:#65758b}.status-pill{background:#def7e8;color:#167447;padding:8px 12px;border-radius:999px;font-size:12px;font-weight:800}.hero-data{display:grid;grid-template-columns:1.2fr 1fr 1fr;background:#fff;border:1px solid #dce5ef;border-radius:14px;padding:14px 18px}.hero-data>div{display:flex;align-items:center;gap:10px;padding:0 18px;border-right:1px solid #e4ebf2}.hero-data>div:last-child{border-right:0}.hero-data span{display:grid;color:#718096;font-size:11px}.hero-data strong{font-size:14px;color:#10213a;margin-top:2px}.top-grid,.bottom-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.form-card{background:#fff;border:1px solid #dce5ef;border-radius:14px;padding:16px;box-shadow:0 2px 10px #18304d08}.section-title{display:flex;align-items:flex-start;gap:9px;margin-bottom:12px}.section-title h2{font-size:15px;margin:0}.section-title p{margin:2px 0 0;color:#748399;font-size:11px}.fields{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.fields label{display:grid;gap:4px}.fields .wide{grid-column:span 2}.fields span{font-size:10px;font-weight:800;color:#53657a;text-transform:uppercase;letter-spacing:.04em}.fields input,.inspection-row input,.notes textarea{width:100%;border:1px solid #d5e0eb;border-radius:7px;background:#fbfdff;color:#10213a;min-height:36px;padding:8px 10px;font:inherit;font-size:12px}.inspection .section-title{align-items:center}.status-key{margin-left:auto;display:flex;gap:14px;font-size:11px}.status-key span{display:flex;align-items:center;gap:5px}.status-key i{width:10px;height:10px;border-radius:50%}.status-key .ok{background:#19a66a}.status-key .attention{background:#f4b91f}.status-key .na{background:#94a3b8}.inspection-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.inspection-row{display:grid;grid-template-columns:minmax(170px,1fr) 190px minmax(120px,.8fr);align-items:center;gap:8px;min-height:45px;border-top:1px solid #edf1f5}.item-name{display:flex;gap:8px;align-items:center;min-width:0}.item-name b{font-size:10px;color:#2f6fca}.item-name span{font-size:12px;font-weight:700}.row-status{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.row-status button{height:28px;border-radius:7px;border:1px solid #d5e0eb;background:#fff;font-size:10px;font-weight:800;color:#526277}.row-status button.active.ok{background:#e8f8f1;border-color:#58c89a;color:#087a4a}.row-status button.active.attention{background:#fff8df;border-color:#f0bf45;color:#9a6700}.row-status button.active.na{background:#eef2f6;border-color:#aebac7;color:#536171}.damages{position:relative}.damage-legend{display:flex;gap:8px;flex-wrap:wrap;position:absolute;right:16px;top:14px}.damage-legend button{display:flex;align-items:center;gap:6px;border:0;background:transparent;color:#53657a;font-size:11px}.damage-legend button.selected{font-weight:800;color:#10213a}.damage-legend i{width:12px;height:12px;border-radius:50%}.views-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.seg-moto,.seg-truck,.seg-machine{grid-template-columns:repeat(4,1fr)}.vehicle-view{position:relative;border:1px solid #e2e9f1;border-radius:10px;padding:8px;background:#fbfdff;min-height:150px;cursor:crosshair;display:grid;align-content:center}.vehicle-view svg{width:100%;height:105px}.vehicle-view>strong{text-align:center;font-size:10px;color:#5e6d80}.damage-dot{position:absolute;width:22px;height:22px;border:3px solid #fff;border-radius:50%;transform:translate(-50%,-50%);color:#fff;font-size:9px;font-weight:900;box-shadow:0 1px 5px #0003}.notes textarea{min-height:150px;resize:vertical}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:12px}.signature-box{border:1px solid #dbe4ed;border-radius:10px;padding:10px}.signature-head{display:flex;justify-content:space-between;align-items:center}.signature-head strong{font-size:11px}.signature-head button{border:0;background:transparent;display:flex;align-items:center;gap:4px;color:#617188;font-size:10px}.signature-box canvas{width:100%;height:112px;margin-top:7px;border:1px dashed #b8c5d2;border-radius:8px;touch-action:none;background:#fff}.signature-box small{font-size:9px;color:#8190a2}.check-error{padding:10px 12px;border:1px solid #fecaca;background:#fff1f1;color:#b42318;border-radius:9px}.check-actions{display:flex;align-items:center;justify-content:flex-end;gap:16px;padding:8px 0 20px;color:#6a798c;font-size:11px}.check-actions button{border:0;background:#1769d1;color:#fff;border-radius:9px;padding:12px 18px;font-weight:800;display:flex;align-items:center;gap:7px}.check-actions button:disabled{opacity:.6}.check-state{max-width:560px;margin:18vh auto;background:#fff;border:1px solid #dce5ef;border-radius:16px;padding:42px;text-align:center}.check-state.success svg{color:#18a66a}.check-state h1{margin:12px 0 5px}.check-state p{color:#6d7c8f}
    @media(max-width:980px){.inspection-grid{grid-template-columns:1fr}.inspection-row{grid-template-columns:minmax(150px,1fr) 180px}.inspection-row>input{grid-column:1/-1;margin-bottom:7px}.views-grid,.seg-moto,.seg-truck,.seg-machine{grid-template-columns:repeat(2,1fr)}}
    @media(max-width:720px){.check-page{padding:0}.check-wrap{gap:8px}.check-top{border-radius:0;height:52px}.secure{font-size:0}.check-heading,.hero-data,.form-card{border-radius:0}.check-heading{align-items:flex-start}.check-heading h1{font-size:23px}.status-pill{font-size:10px}.hero-data{grid-template-columns:1fr;padding:6px 14px}.hero-data>div{border-right:0;border-bottom:1px solid #edf1f5;padding:9px 0}.hero-data>div:last-child{border-bottom:0}.top-grid,.bottom-grid{grid-template-columns:1fr;gap:8px}.fields{grid-template-columns:1fr 1fr}.fields .wide{grid-column:1/-1}.status-key{display:none}.inspection-row{grid-template-columns:1fr}.inspection-row>input{grid-column:auto}.row-status{grid-template-columns:repeat(3,1fr)}.damage-legend{position:static;margin:-2px 0 10px}.views-grid,.seg-moto,.seg-truck,.seg-machine{grid-template-columns:1fr 1fr}.signatures{grid-template-columns:1fr}.check-actions{position:sticky;bottom:0;background:#fff;padding:10px 14px;border-top:1px solid #dde5ee}.check-actions span{display:none}.check-actions button{width:100%;justify-content:center}.vehicle-view{min-height:135px}}
  `}</style></main>;
}
